package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.*;
import java.nio.ByteBuffer;
import java.nio.file.*;
import java.security.*;
import java.time.Duration;
import java.util.*;
import org.apache.ratis.client.RaftClient;
import org.rocksdb.*;

/** Caller-driven fresh-cluster restoration. Provisioning must retain a traffic gate until READY; all transports remain borrowed. */
public final class RatisDatabaseRestoreController implements AutoCloseable {
    public static final int MAX_FILES=1048576;
    public static final long MAX_RETAINED_BYTES=(long)RatisDatabaseRestorePlanner.MAX_IMPORTS*RatisRangeImportController.MAX_SOURCE_BYTES,MAX_METADATA_BYTES=64L*1024*1024*1024;
    public enum Phase { PROVISION, RESERVE, SCHEMA, GENESIS, GRANT, IMPORT, PROPAGATE, BIND, VERIFY, READY }
    public record Execution(RatisNodePlan nodePlan,RaftClient catalogue,Map<UUID,RatisRoutedClient> routed,RatisRangeImportController.DataPlane data){public Execution{Objects.requireNonNull(nodePlan);Objects.requireNonNull(catalogue);routed=Map.copyOf(routed);Objects.requireNonNull(data);}}
    /** Idempotent trusted placement creation/recovery from the exact forced plan, using only archive operator assets. Never opens public USER traffic. */
    @FunctionalInterface public interface Provisioner { Execution provision(RatisDatabaseRestorePlanner.Plan plan,Map<UUID,Path> operatorAssets)throws IOException; }
    public record Progress(Phase phase,int completed,int total){}
    private final Path root;private final RatisDatabaseBackupArchive archive;private final DatabaseBackupManifest complete;private final RatisDatabaseRestorePlanner.Plan plan;private final RatisDatabaseRestoreJournal journal;private final Provisioner provisioner;
    private Execution execution;private boolean busy,closed;
    private RatisDatabaseRestoreController(Path root,RatisDatabaseBackupArchive archive,Provisioner provisioner,RatisDatabaseRestoreJournal journal)throws IOException{
        this.root=root.toAbsolutePath().normalize();this.archive=Objects.requireNonNull(archive);this.provisioner=Objects.requireNonNull(provisioner);this.journal=journal;
        try{complete=DatabaseBackupManifest.decode(journal.fields.get("archive"));plan=RatisDatabaseRestorePlanner.Plan.decode(journal.fields.get("plan"));if(!Arrays.equals(complete.encode(),archive.reopenComplete().encode()) || !plan.archiveId().equals(complete.destination().archiveId()) || plan.roster().clusterId().equals(complete.definition().roster().clusterId()))throw new IOException("Restore archive/fresh plan binding changed");requireBudgets(plan,complete);phase();index();}catch(Exception failure){journal.close();if(failure instanceof IOException io)throw io;throw new IOException("Invalid restore state",failure);}
    }
    public static RatisDatabaseRestoreController create(Path root,RatisDatabaseBackupArchive archive,UUID cluster,List<ReplicaDescriptor> membership,UUID session,long logicalTime,Provisioner provisioner)throws IOException{
        try{Math.addExact(logicalTime,86400000L);var complete=archive.reopenComplete();var plan=RatisDatabaseRestorePlanner.plan(complete,cluster,membership,session,logicalTime);requireBudgets(plan,complete);var fields=new HashMap<String,byte[]>();fields.put("archive",complete.encode());fields.put("plan",plan.encode());fields.put("phase",new byte[]{0});fields.put("index",number(0));return new RatisDatabaseRestoreController(root,archive,provisioner,new RatisDatabaseRestoreJournal(root,fields));}catch(org.rocksdb.RocksDBException failure){throw new IOException("Archive verification failed",failure);}
    }
    public static RatisDatabaseRestoreController reopen(Path root,RatisDatabaseBackupArchive archive,Provisioner provisioner)throws IOException{return new RatisDatabaseRestoreController(root,archive,provisioner,new RatisDatabaseRestoreJournal(root,null));}
    public RatisDatabaseRestorePlanner.Plan plan(){return plan;}
    public Phase phase(){byte[] bytes=journal.fields.get("phase");if(bytes.length!=1 || (bytes[0]&255)>=Phase.values().length)throw new IllegalArgumentException("Invalid restore phase");return Phase.values()[bytes[0]&255];}
    private int index(){int value=ByteBuffer.wrap(journal.fields.get("index")).getInt();if(value<0)throw new IllegalArgumentException("Invalid restore cursor");return value;}
    public Progress step(int budget)throws IOException{begin();try{if(budget<1 || budget>32)throw new IllegalArgumentException("Restore step bound exceeded");if(execution==null)provision();for(int i=0;i<budget && phase()!=Phase.READY;i++)advance();return new Progress(phase(),index(),plan.domains().stream().mapToInt(d->d.imports().size()).sum());}finally{end();}}
    public SessionEpochLedger issuedLedger()throws IOException{begin();try{if(phase()!=Phase.READY)throw new IOException("Restore has not passed complete logical verification");if(execution==null)provision();return issuance();}finally{end();}}
    private void provision()throws IOException{
        journal.save();var assets=new LinkedHashMap<UUID,Path>();for(var asset:complete.operators())assets.put(asset.objectId(),archiveObject(asset.objectId(),true));var result=provisioner.provision(plan,Map.copyOf(assets));var c=result.nodePlan().catalogue();var expected=plan.catalogue();
        if(!result.nodePlan().clusterId().equals(plan.roster().clusterId()) || !result.nodePlan().databaseId().equals(plan.roster().databaseId()) || !c.groupId().equals(expected.groupId()) || !c.directoryColumn().equals(expected.directoryColumn()) || !c.sessionsColumn().equals(expected.sessionsColumn()) || c.epoch()!=expected.epoch() || !Arrays.equals(c.schemaDigest(),expected.schemaDigest()) || !c.replicas().equals(expected.replicas()) || !result.routed().keySet().equals(Set.copyOf(plan.roster().domainIds())))throw new IOException("Provisioning crossed exact fresh restore binding");
        for(var domain:plan.domains())if(!Arrays.equals(result.nodePlan().directory(domain.schema().domainId()).payloadDigest(),domain.initialDirectory().payloadDigest()))throw new IOException("Provisioning changed frozen DATA geometry");
        byte[] retained=journal.fields.get("execution");if(retained!=null && !Arrays.equals(retained,result.nodePlan().identityDigest()))throw new IOException("Provisioned node identity changed across reopen");journal.fields.put("execution",result.nodePlan().identityDigest());journal.save();execution=result;if(phase()==Phase.READY)requireReadyExecution();if(phase()==Phase.PROVISION)move(Phase.RESERVE);
    }
    private void requireReadyExecution()throws IOException {
        var roster=new RatisDatabaseDomainRoster(execution.catalogue(),plan.roster().clusterId(),plan.roster().databaseId(),plan.catalogue());var view=roster.readComplete();if(!view.roster().equals(plan.roster()))throw new IOException("Restore roster changed");var authority=plan.requireExecutionLedger(issuance());
        for(var domain:plan.domains()){var routed=finalRoute(domain);if(!Arrays.equals(view.directories().get(domain.schema().domainId()).payloadDigest(),domain.finalDirectory().payloadDigest()))throw new IOException("Restore directory changed");for(var range:domain.finalDirectory().ranges())routed.stateView(range.groupId()).requireServing(authority);}roster.requireUnchanged(plan.roster());
    }
    private void advance()throws IOException{
        int cursor=index();var domains=plan.domains();var catalogue=plan.catalogue();
        switch(phase()){
            case RESERVE->{var reservations=new ArrayList<RatisColumnAllocation.Reservation>();for(var domain:domains)for(var column:domain.schema().columns())reservations.add(plan.reservation(domain.schema().domainId(),column));if(reservations.isEmpty()){move(Phase.SCHEMA);break;}var allocation=new RatisColumnAllocation(execution.catalogue(),catalogue.groupId(),catalogue.epoch(),catalogue.schemaDigest(),catalogue.directoryColumn());command(allocation.prepareReservations(control(0),reservations,null),Phase.SCHEMA);}
            case SCHEMA->{var domain=domains.get(cursor);var reservations=new HashMap<UUID,RatisColumnAllocation.Reservation>();for(var column:domain.schema().columns())reservations.put(column.columnId(),plan.reservation(domain.schema().domainId(),column));try(var publication=new RatisSchemaPublication(path("schemas").resolve(domain.schema().domainId()+".schema"),execution.catalogue(),execution.nodePlan(),domain.schema(),counter(),Map.of(),Map.of(),reservations)){success(publication.execute());}next(cursor,domains.size(),Phase.GENESIS);}
            case GENESIS->{var domain=domains.get(cursor);var ledger=SessionEpochLedger.initial(plan.roster().clusterId(),plan.roster().databaseId(),plan.authority().logicalTimeMillis());try(var genesis=new RatisCatalogueGenesis(path("genesis").resolve(domain.schema().domainId()+".genesis"),execution.catalogue(),execution.nodePlan(),domain.schema().domainId(),plan.authority().logicalTimeMillis(),cursor==0 ? null : ledger,cursor==0 ? null : plan.roster(),plan.roster())){success(genesis.execute());}next(cursor,domains.size(),Phase.GRANT);}
            case GRANT->{var epochs=epochs();if(!journal.fields.containsKey("pending")){journal.save();var previous=epochs.read();if(previous==null || !previous.grants().isEmpty())throw new IOException("Fresh restore grant requires original grant-free ledger");var prepared=epochs.prepareGrant(control(1),previous,plan.sessionId(),Math.addExact(plan.authority().logicalTimeMillis(),86400000L));journal.fields.put("pending",DistributedCommandCodec.encode(prepared.command()));journal.save();}command(null,Phase.IMPORT);issuance();}
            case IMPORT->{var jobs=imports();var imported=jobs.get(cursor);Path scope=path("imports").resolve(imported.importId().toString());Files.createDirectories(scope);journal.save();try(var controller=new RatisRangeImportController(scope,plan.roster().clusterId(),plan.roster().databaseId(),catalogue,execution.catalogue(),execution.data())){RatisRangeImportController.Handle handle;if(Files.exists(scope.resolve(imported.importId()+".import")))handle=controller.reopen(imported.importId());else{var sources=new HashMap<RatisRangeImportController.Source,Path>();for(var manifest:imported.manifests())for(var column:manifest.columns())for(var file:column.files())sources.put(new RatisRangeImportController.Source(manifest.groupId(),file.fileId()),archiveObject(file.fileId(),false));handle=controller.prepare(imported,sources);}var progress=controller.advance(handle,1);if(progress.phase()==RatisRangeImportController.Phase.DONE){var routed=execution.routed().get(imported.sourceDirectory().domainId());if(routed.directory().generation()<imported.targetDirectory().generation())routed.refresh(imported.targetDirectory());if(!journal.fields.containsKey("pending")){journal.fields.put("pending",DistributedCommandCodec.encode(new DistributedCommand(catalogue.groupId(),catalogue.epoch(),catalogue.schemaDigest(),new OperationId(plan.sessionId(),1,imported.operation().sequence()+1),List.of(),List.of(),imported.operation().sequence())));journal.save();}rawCommand();next(cursor,jobs.size(),Phase.PROPAGATE);}}}
            case PROPAGATE->{var domain=domains.get(cursor);var routed=finalRoute(domain);try(var propagation=new RatisSessionPropagation(Files.createDirectories(path("propagation").resolve(domain.schema().domainId().toString())),epochs(),routed,RangeDirectoryCodec.MAX_RANGES)){var target=plan.requireExecutionLedger(issuance());if(propagation.progress().target()==null)propagation.begin(target);var result=propagation.step(1);if(result.complete() && propagation.covers(target))next(cursor,domains.size(),Phase.BIND);}}
            case BIND->{var ranges=targets();var target=ranges.get(cursor);try(var binding=new RatisSessionMaintenance(path("bindings").resolve(target.getValue().groupId()+".bind"),epochs(),execution.routed().get(target.getKey()),target.getValue().groupId())){if(binding.propagated()==null){if(binding.pendingCommand()==null)binding.prepareBinding(grant(),32);success(binding.execute());}}next(cursor,ranges.size(),Phase.VERIFY);}
            case VERIFY->{verify();move(Phase.READY);}
            default->throw new IOException("Unexpected restore phase");
        }
    }
    private List<RangeImportDefinition> imports(){return plan.domains().stream().flatMap(d->d.imports().stream()).toList();}
    private List<Map.Entry<UUID,RangeDescriptor>> targets(){var result=new ArrayList<Map.Entry<UUID,RangeDescriptor>>();for(var domain:plan.domains())for(var range:domain.finalDirectory().ranges())result.add(Map.entry(domain.schema().domainId(),range));return result;}
    private RatisRoutedClient finalRoute(RatisDatabaseRestorePlanner.Domain domain)throws IOException{var routed=execution.routed().get(domain.schema().domainId());if(routed.directory().generation()<domain.finalDirectory().generation())routed.refresh(domain.finalDirectory());if(!Arrays.equals(routed.directory().payloadDigest(),domain.finalDirectory().payloadDigest()))throw new IOException("Restore final route changed");return routed;}
    private void verify()throws IOException{journal.save();var roster=new RatisDatabaseDomainRoster(execution.catalogue(),plan.roster().clusterId(),plan.roster().databaseId(),plan.catalogue());var view=roster.readComplete();if(!view.roster().equals(plan.roster()))throw new IOException("Restore roster changed");var authority=plan.requireExecutionLedger(issuance());for(var domain:plan.domains()){var routed=finalRoute(domain);if(!Arrays.equals(view.directories().get(domain.schema().domainId()).payloadDigest(),domain.finalDirectory().payloadDigest()))throw new IOException("Restore directory changed");for(var range:domain.finalDirectory().ranges()){routed.stateView(range.groupId()).requireServing(authority);for(var column:domain.schema().columns())if(!Arrays.equals(expected(domain,range,column.columnId()),actual(routed,range,column.columnId())))throw new IOException("Restored logical USER digest differs from archive");}}roster.requireUnchanged(plan.roster());}
    private byte[] actual(RatisRoutedClient routed,RangeDescriptor range,UUID column)throws IOException{var digest=sha();var scope=new TransactionScope(List.of(TransactionScope.Span.range(column,range.lowerInclusive(),range.upperExclusive())));try(var read=routed.openTransaction(scope,Duration.ofSeconds(30))){byte[] resume=null;while(true){var page=read.page(column,range.lowerInclusive(),range.upperExclusive(),false,resume,1024,PhysicalRangePage.MAX_BYTES);for(var row:page.rows())row(digest,row.key(),row.value());if(!page.hasMore())break;resume=page.resumeAfter();}}return digest.digest();}
    private byte[] expected(RatisDatabaseRestorePlanner.Domain domain,RangeDescriptor range,UUID column)throws IOException{var digest=sha();var old=complete.definition().domain(domain.schema().domainId()).directory().ranges().stream().filter(r->Arrays.equals(r.lowerInclusive(),range.lowerInclusive()) && Arrays.equals(r.upperExclusive(),range.upperExclusive())).findFirst().orElseThrow();try{for(var chunk:complete.chunks())if(chunk.groupId().equals(old.groupId()) && chunk.columnId().equals(column) && chunk.objectId()!=null){try(var options=new Options();var reader=new SstFileReader(options);var read=new ReadOptions().setFillCache(false)){reader.open(archiveObject(chunk.objectId(),false).toString());reader.verifyChecksum();try(var iterator=reader.newIterator(read)){for(iterator.seekToFirst();iterator.isValid();iterator.next())row(digest,iterator.key(),iterator.value());iterator.status();}}}}catch(org.rocksdb.RocksDBException failure){throw new IOException("Archive logical digest scan failed",failure);}return digest.digest();}
    private Path archiveObject(UUID id,boolean operator)throws IOException{return archive.objectPath(id,operator);}
    private RatisSessionEpochs epochs(){var c=plan.catalogue();return new RatisSessionEpochs(execution.catalogue(),plan.roster().clusterId(),plan.roster().databaseId(),c.groupId(),c.epoch(),c.schemaDigest(),c.sessionsColumn());}
    private SessionEpochLedger issuance()throws IOException{var issued=epochs().read();if(issued==null)throw new IOException("Restore grant absent");plan.requireExecutionLedger(issued);return issued;}
    private SessionEpochLedger.Grant grant()throws IOException{return issuance().grants().stream().filter(g->g.sessionId().equals(plan.sessionId())).findFirst().orElseThrow();}
    private void command(DistributedCommand prepared,Phase next)throws IOException{if(!journal.fields.containsKey("pending")){journal.fields.put("pending",DistributedCommandCodec.encode(Objects.requireNonNull(prepared)));journal.save();}rawCommand();move(next);}
    private void rawCommand()throws IOException{
        if(!journal.fields.containsKey("pendingResult")) {
            journal.save();var reply=RatisRoutedClient.rpc(()->execution.catalogue().io().send(org.apache.ratis.protocol.Message.valueOf(org.apache.ratis.thirdparty.com.google.protobuf.ByteString.copyFrom(journal.fields.get("pending")))));
            if(reply==null || !reply.isSuccess() || !org.apache.ratis.protocol.RaftGroupId.valueOf(plan.catalogue().groupId()).equals(reply.getRaftGroupId()) || reply.getMessage()==null || reply.getMessage().getContent().size()>CommandResult.MAX_BYTES)throw new IOException("Restore catalogue command reply unavailable");
            final CommandResult result;try{result=CommandResult.decode(reply.getMessage().getContent().toByteArray());}catch(IllegalArgumentException invalid){throw new IOException("Invalid restore catalogue outcome",invalid);}journal.fields.put("pendingResult",result.encode());journal.save();
        }
        success(CommandResult.decode(journal.fields.get("pendingResult")));
    }
    private void finishCommand(){journal.fields.remove("pending");journal.fields.remove("pendingResult");}
    private byte[] counter(){long max=plan.domains().stream().flatMap(d->d.schema().columns().stream()).mapToLong(DistributedSchema.Column::apiId).max().orElse(0);return max==0 ? null : RatisColumnAllocation.counterValue(max);}
    private OperationId control(long sequence){return new OperationId(plan.issuerId(),0,sequence);}
    private void next(int cursor,int size,Phase next)throws IOException{if(cursor+1==size)move(next);else{finishCommand();journal.fields.put("index",number(cursor+1));journal.save();}}
    private void move(Phase next)throws IOException{finishCommand();journal.fields.put("phase",new byte[]{(byte)next.ordinal()});journal.fields.put("index",number(0));journal.save();}
    private Path path(String name)throws IOException{var path=root.resolve(name);Files.createDirectories(path);SessionJournalFiles.force(root);return path;}
    private static void requireBudgets(RatisDatabaseRestorePlanner.Plan plan,DatabaseBackupManifest complete)throws IOException{
        long files=0,bytes=0,metadata=complete.encode().length+plan.encode().length;
        for(var domain:plan.domains())for(var imported:domain.imports()){metadata+=3L*imported.encode().length;for(var manifest:imported.manifests()){files++;bytes+=manifest.encode().length;for(var column:manifest.columns())for(var file:column.files()){files++;bytes=Math.addExact(bytes,file.bytes());}}}
        if(files>MAX_FILES || bytes>MAX_RETAINED_BYTES || metadata>MAX_METADATA_BYTES)throw new IOException("Restore metadata/files/retained bytes exceed declared capacity");
    }
    private static void success(CommandResult result)throws IOException{if(result.status()!=CommandResult.Status.SUCCESS || result.valueCount()!=0)throw new IOException("Frozen restore action failed: "+result.status());}
    private static byte[] number(int value){return ByteBuffer.allocate(4).putInt(value).array();}
    private static MessageDigest sha(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
    private static void row(MessageDigest digest,byte[] key,byte[] value){digest.update(ByteBuffer.allocate(8).putInt(key.length).putInt(value.length).array());digest.update(key);digest.update(value);}
    private synchronized void begin()throws IOException{if(closed || busy)throw new IOException("Restore closed or actual I/O active");busy=true;}
    private synchronized void end(){busy=false;}
    public synchronized void close()throws IOException{if(busy)throw new IOException("Restore I/O still active");if(!closed){journal.close();closed=true;}}
}
